  XB = `Η παρακάτω ενότητα έχει το χαρακτηριστικό δυναμικής αποκάλυψης ενεργοποιημένο. Μπορείτε να κάνετε προεπισκόπηση του χαρακτηριστικού εκκινώντας τη δοκιμή. Αυτό θα επαναφέρεται όταν αποχωρείτε από την καρτέλα προεπισκόπησης.`,
  ZB = `Εκκίνηση τύπου δοκιμής`,
  QB = `Διαγράψαμε τα αρχικά δεδομένα και θα αποκαλύψουμε όλα τα αντικείμενα τυχαία. Θα γίνει αυτόματη ανανέωση σε %1$s δευτερόλεπτα.`,
  $B = `Επιβολή κλήσης υπηρεσίας`,
  eV = `Προβολή ημέρας εκπτώσεων %1$s`,
  tV = `Εκτελείται σε αυτόν τον υπολογιστή μέσω`,
  nV = `Steam Play.`,
  rV = `επιλέχθηκε από εσάς για αυτόν τον τίτλο.`,
  iV = `επιλέχθηκε από εσάς για όλους τους τίτλους.`,
  aV = `επιλέχθηκε από δοκιμή Valve.`,
  oV = `Εκτελείται σε αυτόν τον υπολογιστή μέσω <1>Steam Play.</1>`,
  sV = `%1$s επιλέχθηκε από εσάς για αυτόν τον τίτλο.`,
  cV = `%1$s επιλέχθηκε από δοκιμή Valve.`,
  lV = `Βραβεία Steam`,
  uV = `Υποψήφιος τίτλος`,
  dV = `Υποψήφιος τίτλος Βραβείων Steam`,
  fV = `Προτείνετε τώρα. Ψηφίστε τον Δεκέμβριο.`,
  pV = `Τα Βραβεία Steam αυτού του συμβάντος έχουν λήξει. Ελέγξτε ξανά στις φετινές Φθινοπωρινές και Χειμερινές εκπτώσεις για τα ετήσια Βραβεία Steam!`,
  mV = `Δεκέμβριος %1$s`,
  hV = `Κάντε κλικ παρακάτω για να ψηφίσετε το %1$s:`,
  gV = `Οι δημιουργοί του %1$s θα ήθελαν να το προτείνετε στην παρακάτω κατηγορία.`,
  _V = `Κάντε κλικ εδώ για να προτείνετε το %1$s σε μια κατηγορία στη σελίδα Βραβείων Steam.`,
  vV = `Οι υποψηφιότητες έκλεισαν. Ψηφίστε στις Χειμερινές Εκπτώσεις. Οι νικητές θα ανακοινωθούν στις 2 Ιανουαρίου.`,
