  kV = `Πιο πρωτοποριακό`,
  AV = `Καλύτερο Παιχνίδι στο οποίο Είστε Χάλια`,
  jV = `Καλύτερη Μουσική Υπόκρουση`,
  MV = `Εξαιρετικά πλούσια ιστορία`,
  NV = `Καθίστε αναπαυτικά και χαλαρώστε`,
  PV = `Μην προτείνετε μία συγκεκριμένη κατηγορία και αντ' αυτού επιτρέψτε στους φαν σας να επιλέξουν την κατηγορία που πιστεύουν ότι ταιριάζει στο παιχνίδι σας. Το συμβάν θα εξακολουθεί να συμπεριλαμβάνει ένα σύνδεσμο στη σελίδα υποψηφιοτήτων.`,
  FV = `Χωρίς κατηγορία`,
  IV = `Ίσως ήταν ο συναρπαστικός τρόπος παιχνιδιού και η καθηλωτική του ιστορία. Ίσως οι καλοφτιαγμένοι χαρακτήρες, ο άψογος σχεδιασμός και το εθιστικό του παιχνίδι πολλών παικτών. Όποιος κι αν ήταν ο λόγος, το παιχνίδι που κέρδισε το βραβείο «Παιχνίδι της Χρονιάς 2020» έγραψε κατευθείαν ιστορία.`,
  LV = `Το VR παιχνίδι της χρονιάς δεν μεταμφιέζεται απλώς ως κανονική πραγματικότητα. Αυτό το παιχνίδι βελτιώνει την πραγματικότητα, εκμεταλλευόμενο το μέσο της εικονικής πραγματικότητας και ωθώντας τα όρια του εικονικού βασιλείου.`,
  RV = `Αυτό το παιχνίδι κυκλοφορεί για καιρό. Η ομάδα έχει αφήσει αρκετά πίσω της το ντεμπούτο του δημιουργικού μωρού της, αλλά όντας καλοί γονείς, αυτοί οι δημιουργοί συνεχίζουν να προστατεύουν και να υποστηρίζουν τη δημιουργία τους. Σε αυτό το παιχνίδι, μέχρι και σήμερα, προστίθεται ακόμα νέο περιεχόμενο μετά από τόσα χρόνια.`,
  zV = `Υπάρχουν μερικά παιχνίδια εκεί έξω που δεν είναι τα ίδια όταν τα παίζετε μόνοι. Ίσως χρειάζεστε έναν φίλο να φυλάει τα νώτα σας. Ίσως χρειάζεστε έναν φίλο για να τον μαχαιρώσετε πισώπλατα. Όπως και να 'χει, όσοι μαζεύονται με φίλους για να παίξουν αυτά τα παιχνίδια ρίχνουν πάντα πολύ γέλιο.`,
  BV = `Το οπτικό στιλ δεν φιλοδοξεί να πετύχει γραφική πιστότητα πραγματικού κόσμου (αν και είναι ευγενής στόχος από μόνος του)… περιγράφει μια ξεχωριστή εμφάνιση και αίσθημα που επικαλύπτει ένα ολόκληρο παιχνίδι.`,
  VV = `Οι σχεδιαστές αυτού του παιχνιδιού είναι στην εμπροσθοφυλακή του δημιουργικού πειραματισμού, φέρνοντας μια φρέσκια προοπτική και ριζοσπαστικές εκπλήξεις. Αυτό το παιχνίδι προκάλεσε ευχαρίστηση, έμπνευση και διασκέδασε με φρεσκάδα που δεν έχει παιχτεί ποτέ ξανά.`,
  HV = `Αυτό είναι το παιχνίδι που ανταμείβει την επιμονή και δεν είναι για λιπόψυχους. Είναι το δυσκολότερο παιχνίδι που αγαπήσαμε ποτέ.`,
  UV = `Αυτός ο αφανής ήρωας αξίζει να αναγνωριστεί για την εξαιρετική μουσική του. Βάζει την τέχνη στον καλλιτέχνη! `,
  WV = `Μερικές μέρες, μόνο ένα παιχνίδι με πολλή αφήγηση θα βρει τον στόχο, και αυτό τον πέτυχε διάνα. Είναι τόσο συναρπαστικό όσο μια σαπουνόπερα και καλοφτιαγμένο σαν σειρά τηλεόρασης. Μπράβο που μας κάνετε να νιώθουμε πράγματα!`,
  GV = `Αυτό το παιχνίδι είναι το αντίδοτο σε μια πολυάσχολη μέρα. Είναι ομαλό, είναι χαλαρωτικό, λιώνει τις στεναχώριες σας. Αυτό το παιχνίδι είναι η στιγμή ζεν σας.`,
  KV = `Αλλαγή της πρότασής σας;`,
  qV = `Μπορείτε να προτείνετε μόνο ένα παιχνίδι για κάθε κατηγορία και έχετε ήδη προτείνει το %1$s για αυτή. Θέλετε να προτείνετε το %2$s αντ' αυτού;`,
