  NH = `Το VR Παιχνίδι της Χρονιάς δεν μεταμφιέζεται απλώς ως κανονική πραγματικότητα. Αυτό το παιχνίδι βελτιώνει την πραγματικότητα, εκμεταλλευόμενο το μέσο της εικονικής πραγματικότητας και ωθώντας τα όρια του εικονικού χώρου.`,
  PH = `Αυτό το παιχνίδι κυκλοφορεί εδώ και καιρό. Η ομάδα έχει αφήσει πλέον πίσω της το ντεμπούτο του δημιουργικού της μωρού, αλλά επειδή είναι και καλοί γονείς, αυτοί οι δημιουργοί συνεχίζουν να φροντίζουν και να υποστηρίζουν το δημιούργημά τους. Αυτό το παιχνίδι λαμβάνει νέο περιεχόμενο έως και σήμερα, μετά από όλα αυτά τα χρόνια.`,
  FH = `Υπάρχουν μερικά παιχνίδια εκεί έξω που δεν είναι τα ίδια όταν τα παίζετε χωρίς παρέα. Ίσως χρειάζεστε έναν φίλο να φυλάει τα νώτα σας. Ίσως χρειάζεστε έναν φίλο για να τον μαχαιρώσετε πισώπλατα. Όπως και να 'χει, όσοι μαζεύονται με φίλους για να παίξουν αυτά τα παιχνίδια, ρίχνουν πάντα πολύ γέλιο.`,
  IH = `Το οπτικό στιλ δεν φιλοδοξεί να πετύχει γραφική πιστότητα πραγματικού κόσμου (αν και είναι ευγενής στόχος από μόνος του)… περιγράφει μια ξεχωριστή εμφάνιση και αίσθηση που χαρακτηρίζει ένα ολόκληρο παιχνίδι.`,
  LH = `Οι σχεδιαστές αυτού του παιχνιδιού είναι στην εμπροσθοφυλακή του δημιουργικού πειραματισμού, φέρνοντας μια φρέσκια προοπτική και ριζοσπαστικές εκπλήξεις. Αυτό το παιχνίδι προκάλεσε ευχαρίστηση, έμπνευση και διασκέδασε με φρεσκάδα που δεν έχει παιχτεί ποτέ ξανά.`,
  RH = `Αυτό είναι το παιχνίδι που ανταμείβει την επιμονή και δεν είναι για λιπόψυχους. Είναι το δυσκολότερο παιχνίδι που αγαπήσαμε ποτέ.`,
  zH = `Αυτός ο αφανής ήρωας αξίζει να αναγνωριστεί για την εξαιρετική μουσική του. Βάζει την τέχνη στον καλλιτέχνη! `,
  BH = `Μερικές μέρες, μόνο ένα παιχνίδι με πολλή αφήγηση θα βρει τον στόχο, και αυτό τον πέτυχε διάνα. Είναι τόσο συναρπαστικό όσο μια σαπουνόπερα και καλοφτιαγμένο σαν σειρά τηλεόρασης. Μπράβο που μας κάνετε να νιώθουμε πράγματα!`,
  VH = `Αυτό το παιχνίδι είναι το αντίδοτο σε μια πολυάσχολη μέρα. Είναι ομαλό, είναι χαλαρωτικό, λιώνει τις στεναχώριες σας. Αυτό το παιχνίδι είναι η στιγμή ζεν σας.`,
  HH = `Αυτό το παιχνίδι ήταν τόσο καλό που θέλατε να το πάρετε μαζί σας παντού. Και το κάνατε! Ευτυχώς, όλα εκείνα που σας έκαναν να παίζετε ασταμάτητα στο γραφείο σας, έγιναν ακόμη καλύτερα εν κινήσει.`,
  UH = `Μόνο VR`,
  WH = `Υποστήριξη VR`,
  GH = `Απομένουν %1$s μέχρι την επόμενη κλήρωση!`,
  KH = `Χρόνος μέχρι την επόμενη κλήρωση.`,
  qH = `Συνεχίστε να παρακολουθείτε για μια πιθανότητα να κερδίσετε!`,
