  YH = `Αριθμός τυχερών νικητών ως τώρα!`,
  XH = `Η δωροπροσφορά πλέον τελείωσε. Ευχαριστούμε για τη συμμετοχή σας.`,
  ZH = `Η δωροπροσφορά πλέον τελείωσε με πάνω από %1$s τυχερούς νικητές, ευχαριστούμε για τη συμμετοχή σας.`,
  QH = `Κάντε κλικ για να μάθετε περισσότερα για τα έπαθλα, τους νικητές και τους κανόνες`,
