  gU = `Αδυναμία ανοίγματος φακέλου`,
  _U = `Ο ΜΕΓΑΛΟΣ ΑΓΩΝΑΣ ΤΟΥ ΑΥΤΟΚΡΑΤΟΡΑ`,
  vU = `Οι απαρχές του Κινέζικου Ζωδιακού Κύκλου`,
  yU = `Μέρος I από IV`,
  bU = `Μέρος II από IV`,
  xU = `Μέρος III από IV`,
  SU = `Μέρος IV από IV`,
  CU = `Ο Αυτοκράτορας από νεφρίτη κάλεσε όλα τα πλάσματα του βασιλείου του σε αγώνα ταχύτητας προς το ουράνιο παλάτι του, ανακοινώνοντας ότι τα δώδεκα πρώτα που θα φτάσουν θα τιμηθούν με μια θέση στο νέο του ημερολόγιο.

Ο έξυπνος Αρουραίος ήταν ο πρώτος που διέσχισε τον ποταμό προς την ουράνια πλάση. Μιας και δεν του αρέσει το κολύμπι, ο Αρουραίος σκαρφάλωσε πάνω στο έμπιστο Βόδι και πήδηξε με ενθουσιασμό στον κήπο του αυτοκράτορα πριν οι δυο τους φτάσουν την ακτή.

Το σταθερό Βόδι πέρασε τον ποταμό με άνεση. Χωρίς να τον νοιάζουν τα αποτελέσματα του αγώνα, το Βόδι ήταν χαρούμενο που έπαιξε ένα ρόλο στην επιτυχία του Αρουραίου.`,
  wU = `Η αυτάρκης Τίγρη ταξίδεψε πολύ προσεκτικά χωρίς να προλαβαίνει το Βόδι, σκεπτόμενη πως είναι καλύτερο να φτάσει τρίτη από το να μη φτάσει καθόλου.

Ο γρήγορος Λαγός πήδηξε σε ένα κούτσουρο που επέπλεε γρήγορα στο πουθενά. Αλλά η τύχη απέδωσε εκεί που έπιασε η στρατηγική, και άνεμος αρωγός οδήγησε την αυτοσχέδια βάρκα με ασφάλεια στο δρόμο της.

Η όραση του ιπτάμενου Δράκου αποκάλυψε ένα χωριό σε ανάγκη, οπότε φυσικά ο Δράκος σταμάτησε να βοηθήσει. Χάρισε ακόμα και στο λαγό ένα φύσημα για να διασχίσει το ποτάμι. Η τιμή ήταν πολύ πιο σημαντική από τη νίκη και ο Δράκος βρήκε την πέμπτη θέση αρμόζουσα.`,
  TU = `Το πονηρό Φίδι δεν ενδιαφερόταν για προσπάθεια μεγάλης απόστασης, οπότε τυλίχθηκε απαρατήρητο γύρω από την μπροστινή οπλή του Αλόγου.

Καθώς το Άλογο κάλπαζε προς το τέρμα, το Φίδι ξετυλίχθηκε, τρομάζοντας το άτι αρκετά για να γλιστρήσει στην έκτη θέση, με το νευρικό Άλογο να ακολουθεί πίσω του σε κοντινή απόσταση.`,
  EU = `Η Γίδα, η Μαϊμού και ο Κόκορας εργάστηκαν μαζί, αλλά άφησαν τη Γίδα να κατακτήσει την όγδοη θέση ως backbone του ταξιδιού τους. Η χαρωπή Μαϊμού ήταν η επόμενη και ο αλαζονικός Κόκορας πέρασε τέταρτος, περήφανος πως η σειρά ήταν δίκαιη.

Ο παιχνιδιάρης Σκύλος ενδιαφερόταν κυρίως στο να πλατζουρίζει τριγύρω, νιώθοντας πώς η ενδέκατη θέση ήταν καλή ανταλλαγή για την όλη διασκέδαση.

Τελευταίο ήρθε το Γουρούνι, που είχα σταματήσει για ένα σνακ και για έναν υπνάκο, όντας αρκετό σοφό να γνωρίζει πως κάθε ζώο θα έχει το χρόνο του στη χάρη του Αυτοκράτορα.`,
