  jfe = `Κείμενο σε ομιλία (συνομιλία)`,
  Mfe = `Ομιλία σε κείμενο (συνομιλία)`,
  Nfe = `Τρόπος παιχνιδιού`,
  Pfe = `Οπτικό περιεχόμενο`,
  Ffe = `Ήχος`,
  Ife = `Είσοδος`,
  Lfe = `Προστασία Ανταλλαγών`,
  Rfe = `Μια ανταλλαγή αντιστράφηκε`,
  zfe = `Μια ανταλλαγή αντιστράφηκε`,
  Bfe = `Μία από τις πρόσφατες ανταλλαγές σας αντιστράφηκε από τον χρήστη με τον οποίο κάνατε την ανταλλαγή.`,
  Vfe = `Οι παίκτες στο %1$s είχαν κατά μέσο όρο %2$s ενώ έπαιζαν %3$s`,
  Hfe = `Οι παίκτες στο %1$s είχαν κατά μέσο όρο %2$s ενώ έπαιζαν αυτόν τον τίτλο`,
  Ufe = `%1$s καρέ/δευτ.`,
  Wfe = `Τελευταία ενημέρωση: %1$s`,
  Gfe = `Ανώνυμα δεδομένα ρυθμού καρέ:`,
  Kfe = `Ανώνυμα δεδομένα ρυθμού καρέ`,
  qfe = `Μπορούμε να συλλέγουμε ανώνυμα δεδομένα ρυθμού καρέ όσο παίζετε παιχνίδια και είστε συνδεδεμένοι με τον λογαριασμό Steam σας; Αυτά τα δεδομένα μάς βοηθούν να μαθαίνουμε περισσότερα σχετικά με τη συμβατότητα των παιχνιδιών και να βελτιώνουμε το Steam.`,
  Jfe = `Ανώνυμα δεδομένα ρυθμού καρέ`,
  Yfe = `Εάν επιλέξετε να συμμετάσχετε σε αυτό, τα δεδομένα ρυθμού καρέ του παιχνιδιού θα αποθηκεύονται χωρίς να συνδέονται με τον λογαριασμό Steam σας, αλλά η αναγνώρισή τους θα γίνεται βάσει του είδους υλισμικού με το οποίο παίζετε. Αυτά τα δεδομένα μάς βοηθούν να μαθαίνουμε περισσότερα σχετικά με τη συμβατότητα των παιχνιδιών και να βελτιώνουμε την εμπειρία σε συσκευές που εκτελούν Steam.`,
  Xfe = `Εάν θέλετε να αλλάξετε τη ρύθμιση αργότερα, μπορείτε να τη βρείτε στις <1>Ρυθμίσεις λογαριασμού Steam > Δεδομένα και περιήγηση</1>.`,
  Zfe = `Μάθετε περισσότερα`,
  Qfe = `Συμβατότητα με Steam Deck`,
  $fe = `Steam Deck Verified – Σχόλια και παρατηρήσεις πελατών`,
  epe = `Δεν υπάρχουν διαθέσιμα δεδομένα`,
  tpe = `Το %1$s των ερωτηθέντων συμφωνούν με την αξιολόγηση «%2$s» αυτού του παιχνιδιού.`,
  npe = `Ενδεικτικά, το μέσο ποσοστό συμφωνίας όσον αφορά την αξιολόγηση του συνόλου των παιχνιδιών που είναι «Επαληθευμένα για Steam Deck» είναι %1$s.`,
  rpe = `%1$s%`,
  ipe = `Παρέχουμε αυτά τα δεδομένα επειδή, ενώ οι πελάτες συμφωνούν κατά πλειοψηφία με την αξιολόγηση «Επαληθευμένο» για τους τίτλους (>%1$s%), μπορεί να είναι χρήσιμα για να κατανοήσουμε καλύτερα τις εμπειρίες των πελατών που διαφωνούν, ιδιαίτερα στο πλαίσιο ενός συγκεκριμένου τίτλου ή μιας ενημέρωσης.`,
  ape = `Επιδόσεις`,
  ope = `Αναγνωσιμότητα`,
  spe = `Σταθερότητα`,
  cpe = `Είσοδος`,
  lpe = `Άλλα`,
