  dpe = `Οι πελάτες που %1$s με την κατάσταση «%2$s» του παιχνιδιού ανέφεραν τους ακόλουθους λόγους ως προς το γιατί διαφωνούν.`,
  fpe = `δεν συμφώνησαν`,
  ppe = `Δεδομένα ρυθμού καρέ του Steam Deck`,
  mpe = `Μέσος ρυθμός καρέ Steam Deck`,
  hpe = `Ο μέσος ρυθμός καρέ που αναφέρεται για το %1$s στο %2$s είναι %3$s`,
  gpe = `Ο μέσος ρυθμός καρέ που αναφέρεται για αυτό το παιχνίδι στο %1$s είναι %2$s`,
  _pe = `%1$s καρέ/δευτ.`,
  vpe = `Τα δεδομένα ρυθμού καρέ του Steam Deck βασίζονται σε αναφορές ρυθμού καρέ σε διάστημα %1$s ημερών, από πελάτες του Steam Deck που επέλεξαν να παράσχουν δεδομένα ρυθμού καρέ.`,
  ype = `Τα δεδομένα ρυθμού καρέ του Steam Deck βασίζονται σε αναφορές ρυθμού καρέ από πελάτες του Steam Deck που επέλεξαν να παράσχουν δεδομένα ρυθμού καρέ.`,
  bpe = `Σημείωση: Δεν παρέχεται διακύμανση επί του παρόντος, αλλά προβλέπεται να διατεθεί κατά τη διάρκεια της έκδοσης βήτα. Με τα δεδομένα διακύμανσης, θα μπορείτε να δείτε αν ο ρυθμός καρέ είναι σταθερός ή κυμαίνεται σε μεγάλο βαθμό.`,
  xpe = `Λόγος`,
