  wpe = `Τα δεδομένα ιστογράμματος βασίζονται σε αναφορές ρυθμού καρέ για αυτό το παιχνίδι από πελάτες σε %1$s που επέλεξαν να παράσχουν δεδομένα ρυθμού καρέ.`,
